/**
 * Gmail Node - Version 2.1
 * Discriminator: resource=thread, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  gmailOAuth2: CredentialReference;
}

export type GmailV21ThreadGetParams = {
  resource: 'thread';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * The ID of the thread you are operating on
 */
    threadId: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint Keep true by default. When true, returns lightweight metadata (labels, subject, from, to, snippet) for each message in the thread. When false, fetches and parses the full raw thread (adds html, text, textAsHtml, headers, attachments for every message), which uses much more memory and is a common cause of out-of-memory crashes. Only set false when the email body is actually required, e.g. for AI classification, summarization, or content processing.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to return only thread messages
     * @default true
     */
    returnOnlyMessages?: boolean | Expression<boolean>;
  };
};

export type GmailV21ThreadGetOutput = {
  historyId?: string;
  id?: string;
  messages?: Array<{
    'ARC-Authentication-Results'?: string;
    'ARC-Message-Signature'?: string;
    'ARC-Seal'?: string;
    'Authentication-Results'?: string;
    'Content-Type'?: string;
    Date?: string;
    'Delivered-To'?: string;
    'DKIM-Signature'?: string;
    From?: string;
    historyId?: string;
    id?: string;
    internalDate?: string;
    labels?: Array<{
      id?: string;
      name?: string;
    }>;
    'Message-ID'?: string;
    'MIME-Version'?: string;
    payload?: {
      body?: {
        data?: string;
        size?: number;
      };
      filename?: string;
      mimeType?: string;
      partId?: string;
      parts?: Array<{
        body?: {
          data?: string;
          size?: number;
        };
        filename?: string;
        headers?: Array<{
          name?: string;
          value?: string;
        }>;
        mimeType?: string;
        partId?: string;
      }>;
    };
    Received?: string;
    'Received-SPF'?: string;
    'Return-Path'?: string;
    sizeEstimate?: number;
    snippet?: string;
    Subject?: string;
    threadId?: string;
    To?: string;
    'X-Google-Smtp-Source'?: string;
    'X-Received'?: string;
  }>;
};

export type GmailV21ThreadGetNode = {
  type: 'n8n-nodes-base.gmail';
  version: 2.1;
  config: NodeConfig<GmailV21ThreadGetParams> & { credentials?: Credentials };
  output?: Items<GmailV21ThreadGetOutput>;
};